"""Physical encounter integration on a local development game; no online account cheats."""
import json,os
from pathlib import Path
from playwright.sync_api import sync_playwright
OUT=Path('docs/pr21-review');OUT.mkdir(parents=True,exist_ok=True)
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--disable-dev-shm-usage']);page=browser.new_page(viewport={'width':844,'height':390},is_mobile=True,has_touch=True,reduced_motion='reduce');errors=[]
 page.on('pageerror',lambda e:errors.append(str(e)));page.on('response',lambda r:errors.append(str(r.status)+' '+r.url) if r.status>=400 else None)
 page.add_init_script('window.requestAnimationFrame=()=>0;window.cancelAnimationFrame=()=>{};')
 page.goto(os.environ.get('ETERNA_URL','http://127.0.0.1:5173'),wait_until='domcontentloaded');page.wait_for_function('!!window.__ETERNA__',polling=100,timeout=90000)
 page.add_style_tag(content='.game-canvas{visibility:hidden!important}#app{background:#10192b}')
 page.locator('[data-start]').click(force=True);choice=page.locator('[data-do="class"][data-id="warlock"]')
 if choice.count() and choice.is_visible():choice.click(force=True)
 close=page.locator('.adventure-layer [data-do="close"]')
 if close.count() and close.is_visible():close.click(force=True)
 page.evaluate('''async()=>{const g=window.__ETERNA__;await Promise.all([g.terrain.ready,g.activityScene.ready]);g.running=true;g.hero.godMode=true;g.renderer.render=()=>{};g.composer.render=()=>{};window.clock=performance.now();window.step=(n=1)=>{for(let i=0;i<n;i++){clock+=50;g.frame(clock)}};window.at=id=>{const s=g.activities.sites.find(s=>s.id===id);g.hero.teleportTo(g.hero.position.clone().set(s.x,g.terrain.heightAt(s.x,s.z)+.5,s.z));for(let i=0;i<3;i++)g.activities.update(.1,g.hero);return s};window.clearGuards=id=>{for(const e of [...g.enemies.enemies])if(e.activity?.id===id&&e.alive)e.receiveDamage(e.hp)};}''')
 print('CONTRACTS AND CAMPAIGN UI',flush=True)
 page.locator('.hud-contracts-shortcut').click();page.screenshot(path=str(OUT/'contracts.png'),animations='disabled');page.locator('[data-bounty="accept"]').click();assert page.evaluate("window.__ETERNA__.quests.active().category")=='contract'
 page.locator('[data-bounty="tab"][data-id="campaign"]').click();assert page.locator('.campaign-stage').count()==12;page.screenshot(path=str(OUT/'campaign-three-acts.png'),animations='disabled');page.locator('[data-bounty="close"]').click()
 print('GUARDED CAMP',flush=True)
 camp=page.evaluate('''()=>{const g=window.__ETERNA__,s=at('aurora-camp-0');g.activities.interact(g.hero,s.id);const before=g.drops.length,state=g.activities.state(s.id),guards=state.members.size;clearGuards(s.id);const deathDrops=g.drops.length;g.activities.interact(g.hero,s.id);const loot=g.drops.length;g.activities.interact(g.hero,s.id);return {guards,lockedBefore:before===0,opened:loot>deathDrops,noDuplicate:g.drops.length===loot,ownedLimit:g.enemies.enemies.filter(e=>e.activity&&e.alive).length<=24}}''');assert camp['guards']>=6 and camp['lockedBefore'] and camp['opened'] and camp['noDuplicate'] and camp['ownedLimit'],camp
 print('DEFENSE: 45 SECONDS / THREE WAVES',flush=True)
 defense=page.evaluate('''async()=>{const g=window.__ETERNA__,{QUEST_STORY}=await import('/src/rpg/QuestSystem.ts');const index=QUEST_STORY.findIndex(q=>q.id==='story-aurora-defense');g.quests.restore({schema:3,claimed:QUEST_STORY.slice(0,index).map(q=>q.id)});at('aurora-defense-0');for(const e of [...g.enemies.enemies])if(e.activity&&e.alive)e.receiveDamage(e.hp);g.activities.interact(g.hero,'aurora-defense-0');const s=g.activities.state('aurora-defense-0');for(let n=0;n<910;n++){clearGuards(s.site.id);g.fieldProgress.tick(.05);g.activities.update(.05,g.hero);}return {waves:s.wave,ready:g.quests.progressOf(g.quests.activeStory()).ready,mode:s.mode}}''');assert defense=={'waves':3,'ready':True,'mode':'cooldown'},defense
 print('ELITE REAL DEATH / GUARANTEED DROP',flush=True)
 elite=page.evaluate('''()=>{const g=window.__ETERNA__,s=at('aurora-captain-2'),state=g.activities.state(s.id),e=g.enemies.enemies.find(e=>state.members.has(e.id));const scale=e.model.scale.x;e.receiveDamage(e.hp);const drop=g.drops.at(-1);return {scale,cooldown:!g.fieldProgress.ready(s.id),rarity:drop.item.rarity,fragments:drop.fieldExtras.skinFragments,locked:drop.fieldExtras.lockedChests}}''');assert elite['scale']==2.5 and elite['cooldown'] and elite['rarity'] in ['rare','epic'] and elite['fragments']>=3 and elite['locked']==1,elite
 print('MASSACRE FROM REAL ENEMY DEATHS',flush=True)
 massacre=page.evaluate('''()=>{const g=window.__ETERNA__;g.massacre.reset();g.hero.teleportTo(g.hero.position.clone().set(-10,g.terrain.heightAt(-10,-25)+.5,-25));for(let i=0;i<50;i++){const e=g.enemies.spawn('slime',g.hero.position.clone().add({x:0,y:0,z:4}),1);e.receiveDamage(e.hp);}step(1);return {kills:g.massacre.kills,bonus:g.massacre.bonus,chests:g.activities.targets.filter(d=>d.kind==='massacre').length}}''');assert massacre=={'kills':50,'bonus':.5,'chests':1},massacre;page.wait_for_timeout(4200);page.screenshot(path=str(OUT/'massacre-hud.png'),animations='disabled')
 print('COLLECT AND SPEND FIELD REWARDS',flush=True)
 pickup=page.evaluate('''()=>{const g=window.__ETERNA__,drop=g.drops.find(d=>d.fieldExtras?.lockedChests);const id=drop.id,before=g.fieldProgress.balances.lockedChests;g.events.emit('loot',drop);g.events.emit('loot',drop);const after=g.fieldProgress.balances.lockedChests;return {delta:after-before,removed:!g.drops.some(d=>d.id===id)}}''');assert pickup=={'delta':1,'removed':True},pickup
 print('RIFT THREE WAVES AND DEMON',flush=True)
 rift=page.evaluate('''()=>{const g=window.__ETERNA__,s=at('aurora-rift-0');for(const e of [...g.enemies.enemies])if(e.activity&&e.alive)e.receiveDamage(e.hp);g.fieldProgress.cooldown('aurora-rift-schedule',0);g.activities.update(.1,g.hero);const state=g.activities.activeRift;for(let i=0;i<4;i++){g.fieldProgress.tick(.1);g.activities.update(.1,g.hero);clearGuards(s.id);}const before=g.drops.length;g.activities.update(.1,g.hero);const first=g.drops.length;g.activities.update(.1,g.hero);return {wave:state.wave,mode:state.mode,rewardDrops:first-before,idempotent:g.drops.length===first}}''');assert rift=={'wave':4,'mode':'cooldown','rewardDrops':5,'idempotent':True},rift
 page.evaluate('window.__ETERNA__.openContracts()');page.locator('[data-bounty="tab"][data-id="contract"]').click();page.locator('[data-bounty="claim"]').click();contract=page.evaluate("()=>({serial:window.__ETERNA__.quests.contract('aurora').serial,renown:window.__ETERNA__.fieldProgress.balances.renown})");assert contract=={'serial':1,'renown':1},contract;page.locator('[data-bounty="tab"][data-id="treasure"]').click();page.screenshot(path=str(OUT/'field-treasures.png'),animations='disabled')
 assert not errors,errors;report={'viewport':'844x390','camp':camp,'defense':defense,'elite':elite,'massacre':massacre,'pickup':pickup,'rift':rift,'contract':contract,'errors':errors,'note':'God mode/direct damage used only in local DEV to exercise real encounter deaths. Render calls stubbed; separate GLB review renders production assets.'};(OUT/'browser-report.json').write_text(json.dumps(report,indent=2));print(json.dumps(report,indent=2));browser.close()
